"""Writes the pictures in res/pad_icons (*.png) into src/pad_icons_art.h: they're built into the
program, so there are no files to lose. Drawn by tools/pad_icons/make_playstation_icons.ps1.
    python tools/pad_icons/embed_png.py
"""
import os

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')
art = os.path.join(root, 'res', 'pad_icons')
names = sorted(f[:-4] for f in os.listdir(art) if f.endswith('.png'))
out = ['// Generated by tools/pad_icons/embed_png.py from res/pad_icons/*.png (drawn by',
       '// tools/pad_icons/make_playstation_icons.ps1). Do not edit.',
       '#pragma once', '', '#include <cstddef>', '']
for name in names:
    data = open(os.path.join(art, name + '.png'), 'rb').read()
    out.append(f'inline constexpr unsigned char kPadPng_{name}[{len(data)}] = {{')
    for i in range(0, len(data), 20):
        out.append('    ' + ', '.join(f'0x{b:02X}' for b in data[i:i + 20]) + ',')
    out.append('};')
    print(f'{name}.png: {len(data)} bytes')
out += ['', 'struct PadIconsPng {', '  const char* name;', '  const unsigned char* data;',
        '  size_t size;', '};', 'inline constexpr PadIconsPng kPadIconsPngs[] = {']
out += [f'    {{"{n}", kPadPng_{n}, sizeof(kPadPng_{n})}},' for n in names]
out += ['};', '']
open(os.path.join(root, 'src', 'pad_icons_art.h'), 'w', newline='\n').write('\n'.join(out))
print('src/pad_icons_art.h written')
